export interface IBaseRepository<T> {
  findById(id: string, client?: PoolClient): Promise<T | null>;
  findAll(client?: PoolClient): Promise<T[]>;
  create(entity: Omit<T, 'id'>, client?: PoolClient): Promise<T>;
  update(id: string, entity: Partial<T>, client?: PoolClient): Promise<T | null>;
  delete(id: string, client?: PoolClient): Promise<boolean>;
}

export abstract class BaseRepository<T extends { id: string }> implements IBaseRepository<T> {
  protected abstract readonly tableName: string;
  protected readonly pool: Pool;

  constructor(poolOverride?: Pool) {
    this.pool = poolOverride ?? pool;
  }

  async findById(id: string, client?: PoolClient): Promise<T | null> {
    const executor = client ?? this.pool;
    const result: QueryResult<T> = await executor.query(
      `SELECT * FROM ${this.tableName} WHERE id = $1`,
      [id],
    );
    return result.rows[0] ?? null;
  }

  async findAll(client?: PoolClient): Promise<T[]> {
    const executor = client ?? this.pool;
    const result: QueryResult<T> = await executor.query(
      `SELECT * FROM ${this.tableName}`,
    );
    return result.rows;
  }

  async create(entity: Omit<T, 'id'>, client?: PoolClient): Promise<T> {
    const executor = client ?? this.pool;
    const keys = Object.keys(entity as Record<string, unknown>);
    const values = Object.values(entity as Record<string, unknown>);
    const placeholders = keys.map((_, i) => `$${i + 1}`).join(', ');
    const columns = keys.join(', ');

    const result: QueryResult<T> = await executor.query(
      `INSERT INTO ${this.tableName} (${columns}) VALUES (${placeholders}) RETURNING *`,
      values,
    );
    return result.rows[0];
  }

  async update(id: string, entity: Partial<T>, client?: PoolClient): Promise<T | null> {
    const executor = client ?? this.pool;
    const keys = Object.keys(entity as Record<string, unknown>);
    if (keys.length === 0) {
      return this.findById(id, client);
    }

    const values = Object.values(entity as Record<string, unknown>);
    const setClauses = keys.map((key, i) => `${key} = $${i + 1}`).join(', ');

    const result: QueryResult<T> = await executor.query(
      `UPDATE ${this.tableName} SET ${setClauses} WHERE id = $${keys.length + 1} RETURNING *`,
      [...values, id],
    );
    return result.rows[0] ?? null;
  }

  async delete(id: string, client?: PoolClient): Promise<boolean> {
    const executor = client ?? this.pool;
    const result: QueryResult = await executor.query(
      `DELETE FROM ${this.tableName} WHERE id = $1`,
      [id],
    );
    return (result.rowCount ?? 0) > 0;
  }

  protected async queryWithClient<R extends QueryResultRow>(
    client: PoolClient,
    sql: string,
    params: unknown[] = [],
  ): Promise<QueryResult<R>> {
    return client.query<R>(sql, params);
  }
}

import { PoolClient } from 'pg';
import { IBaseRepository, BaseRepository } from 'shared/base-repository';
import { LeaveBalance } from './balance.model';

export interface ILeaveBalanceRepository extends IBaseRepository<LeaveBalance> {
  findByEmployeeId(employeeId: string, client?: PoolClient): Promise<LeaveBalance[]>;
  findByEmployeeAndPolicy(
    employeeId: string,
    leavePolicyId: string,
    client?: PoolClient,
  ): Promise<LeaveBalance | null>;
  findByEmployeeAndFiscalYear(
    employeeId: string,
    fiscalYear: number,
    client?: PoolClient,
  ): Promise<LeaveBalance[]>;
  findActiveByEmployee(employeeId: string, client?: PoolClient): Promise<LeaveBalance[]>;
  upsert(
    balance: Omit<LeaveBalance, 'id' | 'createdAt' | 'updatedAt'>,
    client?: PoolClient,
  ): Promise<LeaveBalance>;
}

export class LeaveBalanceRepository
  extends BaseRepository<LeaveBalance>
  implements ILeaveBalanceRepository
{
  protected readonly tableName = 'leave_balances';

  async findByEmployeeId(employeeId: string, client?: PoolClient): Promise<LeaveBalance[]> {
    const executor = client ?? this.pool;
    const result = await executor.query(
      `SELECT * FROM ${this.tableName} WHERE employee_id = $1`,
      [employeeId],
    );
    return result.rows;
  }

  async findByEmployeeAndPolicy(
    employeeId: string,
    leavePolicyId: string,
    client?: PoolClient,
  ): Promise<LeaveBalance | null> {
    const executor = client ?? this.pool;
    const result = await executor.query(
      `SELECT * FROM ${this.tableName} WHERE employee_id = $1 AND leave_policy_id = $2`,
      [employeeId, leavePolicyId],
    );
    return result.rows[0] ?? null;
  }

  async findByEmployeeAndFiscalYear(
    employeeId: string,
    fiscalYear: number,
    client?: PoolClient,
  ): Promise<LeaveBalance[]> {
    const executor = client ?? this.pool;
    const result = await executor.query(
      `SELECT * FROM ${this.tableName} WHERE employee_id = $1 AND fiscal_year = $2`,
      [employeeId, fiscalYear],
    );
    return result.rows;
  }

  async findActiveByEmployee(employeeId: string, client?: PoolClient): Promise<LeaveBalance[]> {
    const executor = client ?? this.pool;
    const result = await executor.query(
      `SELECT * FROM ${this.tableName} WHERE employee_id = $1 AND status = 'ACTIVE'`,
      [employeeId],
    );
    return result.rows;
  }

  async upsert(
    balance: Omit<LeaveBalance, 'id' | 'createdAt' | 'updatedAt'>,
    client?: PoolClient,
  ): Promise<LeaveBalance> {
    const executor = client ?? this.pool;
    const result = await executor.query(
      `INSERT INTO ${this.tableName} (employee_id, leave_policy_id, total_entitlement, used_days, remaining_days, fiscal_year, status)
       VALUES ($1, $2, $3, $4, $5, $6, $7)
       ON CONFLICT (employee_id, leave_policy_id, fiscal_year)
       DO UPDATE SET
         total_entitlement = EXCLUDED.total_entitlement,
         used_days = EXCLUDED.used_days,
         remaining_days = EXCLUDED.remaining_days,
         status = EXCLUDED.status,
         updated_at = NOW()
       RETURNING *`,
      [
        balance.employeeId,
        balance.leavePolicyId,
        balance.totalEntitlement,
        balance.usedDays,
        balance.remainingDays,
        balance.fiscalYear,
        balance.status,
      ],
    );
    return result.rows[0];
  }
}
